SELECT CASE WHEN s.rating >= 4.0 THEN 'high' WHEN s.rating >= 1.8 THEN 'mid' ELSE 'low' END AS rating_bucket, s.country, ROUND((100 * SUM(CASE WHEN p.brand = 'Acme' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_acme, MAX(p.price) AS max_price FROM products p LEFT JOIN suppliers s ON s.id = p.supplier_id WHERE p.category IN ('Fashion', 'Electronics', 'Books') GROUP BY CASE WHEN s.rating >= 4.0 THEN 'high' WHEN s.rating >= 1.8 THEN 'mid' ELSE 'low' END, s.country
